const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Sindh province geometry (approximate boundaries)
  const sindh = ee.Geometry.Polygon([
    [[67.0, 23.5], [71.0, 23.5], [71.0, 28.5], [67.0, 28.5], [67.0, 23.5]]
  ]);

  // Define date ranges (±15 days window for better data availability)
  const date2019_start = '2019-09-14';
  const date2019_end = '2019-09-28';
  const date2020_start = '2020-09-14';
  const date2020_end = '2020-09-28';

  // Load Sentinel-1 SAR data
  const s1_2019 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(sindh)
    .filterDate(date2019_start, date2019_end)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const s1_2020 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(sindh)
    .filterDate(date2020_start, date2020_end)
    .filter(ee.Filter.eq('instrumentMode', 'IW'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const size2019 = s1_2019.size().getInfo();
  const size2020 = s1_2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log('Missing data for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Create median composites
  const img2019 = s1_2019.median();
  const img2020 = s1_2020.median();

  // Detect water (VV < -15 dB indicates water)
  const water2019 = img2019.lt(-15);
  const water2020 = img2020.lt(-15);

  // Calculate water extent (sum of water pixels)
  const extent2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sindh,
    scale: 3000,
    maxPixels: 1e9
  }).get('VV');

  const extent2020 = water2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sindh,
    scale: 3000,
    maxPixels: 1e9
  }).get('VV');

  // Calculate pixel counts to check validity
  const count2019 = water2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sindh,
    scale: 3000,
    maxPixels: 1e9
  }).get('VV');

  const waterExtent2019 = extent2019.getInfo();
  const waterExtent2020 = extent2020.getInfo();
  const pixelCount2019 = count2019.getInfo();

  console.log(`2019 Water Pixels: ${waterExtent2019}`);
  console.log(`2020 Water Pixels: ${waterExtent2020}`);
  console.log(`Total Pixels Analyzed: ${pixelCount2019}`);

  if (pixelCount2019 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (waterExtent2019 === null || waterExtent2020 === null || 
      isNaN(waterExtent2019) || isNaN(waterExtent2020)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  const difference = waterExtent2020 - waterExtent2019;
  const percentChange = ((difference / waterExtent2019) * 100).toFixed(2);

  console.log(`Change: ${difference} pixels (${percentChange}%)`);

  if (waterExtent2020 > waterExtent2019) {
    console.log('Surface water extent INCREASED in 2020.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Surface water extent did NOT increase in 2020.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
